import { useRef, useState, useEffect } from 'react'
import {
    getDeliveryReturnList,
    updateDeliveryReturnStatus,
    PlatformUserTypes,
} from '@/apis/admin/platform-user'
import { getShopPlatformList } from '@/apis/admin/system-config'
import { SystemConfigTypes } from '@/apis/admin/system-config/types'
import ExcelTable from '@/components/exportExcel'
import AddDeliveryReturnModal from './components/AddDeliveryReturnModal'
import {
    ActionType,
    ProFormInstance,
    ProColumns,
} from '@ant-design/pro-components'
import {
    Button,
    message,
    Tag,
    Tooltip,
    Popconfirm,
} from 'antd'
import {
    PlusOutlined,
    DeleteOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import dayjs from 'dayjs'

// 格式化时间
const formatTime = (time: string) => {
    if (!time) {
return '-'
}
    return dayjs(time).format('YYYY-MM-DD HH:mm:ss')
}

const ReturnDeliveryPerson: React.FC = () => {
    const actionRef = useRef<ActionType>()
    const formRef = useRef<ProFormInstance>()
    const [modalVisible, setModalVisible] = useState(false)
    const [platformOptions, setPlatformOptions] = useState<Record<string, { text: string }>>({})

    // 加载电商平台列表（用于表格筛选）
    const loadShopPlatformList = async () => {
        try {
            const res = await getShopPlatformList({ status: 1, pageSize: 100 })
            if (res.code === ResultEnum.SUCCESS && res.data?.list) {
                const options: Record<string, { text: string }> = {}
                res.data.list.forEach((item: SystemConfigTypes.ShopPlatformListDto) => {
                    options[item.id] = { text: item.name }
                })
                setPlatformOptions(options)
            }
        } catch (e) {
            console.error('获取电商平台列表失败:', e)
        }
    }

    useEffect(() => {
        loadShopPlatformList()
    }, [])

    // 导出列表
    const handleExport = () => {
        message.info('导出功能开发中')
    }

    // 打开新增绑定弹窗
    const handleOpenAdd = () => {
        setModalVisible(true)
    }

    // 保存成功回调
    const handleSaveSuccess = () => {
        setModalVisible(false)
        actionRef.current?.reload()
    }

    // 解绑
    const handleUnbind = async (record: PlatformUserTypes.DeliveryReturnListDto) => {
        try {
            const res = await updateDeliveryReturnStatus(record.id, {
                id: record.id,
                status: 2
            })

            if (res.code === ResultEnum.SUCCESS) {
                message.success('已解绑')
                actionRef.current?.reload()
            } else {
                message.error(res.message || '操作失败')
            }
        } catch (e) {
            message.error('操作失败')
        }
    }

    // 表格列定义
    const columns: ProColumns<PlatformUserTypes.DeliveryReturnListDto>[] = [
        {
            title: '绑定ID',
            dataIndex: 'id',
            key: 'id',
            width: 100,
            hideInSearch: true,
            render: (text) => (
                <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
                    {text}
                </span>
            ),
        },
        {
            title: '设备编号',
            dataIndex: 'imei',
            key: 'imei',
            width: 160,
            render: (text) => (
                <span style={{ fontFamily: 'Courier New, monospace' }}>
                    {text}
                </span>
            ),
        },
        {
            title: '柜机地址',
            key: 'address',
            width: 240,
            hideInSearch: true,
            render: (_, record) => (
                <span>
                    {record.provinceName}{record.cityName}{record.areaName}
                    {record.communityName ? ` ${record.communityName}` : ''}
                </span>
            ),
        },
        {
            title: '电商平台',
            dataIndex: 'platformId',
            key: 'platformId',
            width: 120,
            hideInTable: true,
            valueType: 'select',
            valueEnum: platformOptions,
        },
        {
            title: '电商平台',
            dataIndex: 'platformName',
            key: 'platformName_display',
            width: 120,
            hideInSearch: true,
            render: (text) => <Tag color="blue">{text}</Tag>,
        },
        {
            title: '配送员姓名',
            dataIndex: 'courierName',
            key: 'courierName',
            width: 120,
        },
        {
            title: '配送员手机',
            dataIndex: 'courierPhone',
            key: 'courierPhone',
            width: 140,
        },
        {
            title: '创建时间',
            dataIndex: 'createdAt',
            key: 'createdAt',
            width: 170,
            hideInSearch: true,
            render: (text) => (
                <span style={{ fontSize: 13, whiteSpace: 'nowrap' }}>
                    {formatTime(text as string)}
                </span>
            ),
        },
        {
            title: '操作',
            key: 'option',
            valueType: 'option',
            fixed: 'right',
            width: 80,
            render: (_, record) => [
                <Tooltip title="解绑" key={`${record.id}-unbind`}>
                    <Popconfirm
                        title="确定解绑该设备吗？"
                        description={`解绑后该设备将不再接收${record.platformName}平台的退货订单。`}
                        onConfirm={() => handleUnbind(record)}
                    >
                        <Button
                            type="link"
                            danger
                            title="解绑"
                            icon={<DeleteOutlined />}
                        />
                    </Popconfirm>
                </Tooltip>,
            ],
        },
    ]

    return (
        <>
            <ExcelTable
                key="return-delivery-list"
                formRef={formRef}
                columns={columns}
                requestFn={async (params) => {
                    const { page, pageSize, imei, provinceId, cityId, areaId, platformId, courierPhone, ...rest } = params
                    return await getDeliveryReturnList({
                        page,
                        pageSize,
                        imei,
                        provinceId,
                        cityId,
                        areaId,
                        platformId,
                        courierPhone,
                        ...rest
                    })
                }}
                actionRef={actionRef}
                rowSelection={false}
                options={{
                    fullScreen: false,
                    reload: true,
                    setting: false,
                    density: false
                }}
                toolBarRenderFn={() => [
                    <Button
                        key="add"
                        type="primary"
                        icon={<PlusOutlined />}
                        onClick={handleOpenAdd}
                    >
                        新增绑定
                    </Button>,
                ]}
                scroll={{ x: 1200 }}
            />

            {/* 新增绑定弹窗 */}
            <AddDeliveryReturnModal
                open={modalVisible}
                onCancel={() => setModalVisible(false)}
                onSuccess={handleSaveSuccess}
            />
        </>
    )
}

export default ReturnDeliveryPerson