import { useState, useEffect } from 'react'
import {
  addDeliveryReturn,
  PlatformUserTypes,
  getCourierUserList
} from '@/apis/admin/platform-user'
import { DeviceManagementTypes } from '@/apis/admin/device-management'
import { getShopPlatformList } from '@/apis/admin/system-config'
import { SystemConfigTypes } from '@/apis/admin/system-config/types'
import DeviceSelector from '@/components/DeviceSelector'
import { Modal, Form, Select, message } from 'antd'
import { ResultEnum } from '@/utils/enums/httpEnum'

interface AddDeliveryReturnModalProps {
  open: boolean
  onCancel: () => void
  onSuccess: () => void
}

const AddDeliveryReturnModal: React.FC<AddDeliveryReturnModalProps> = ({
  open,
  onCancel,
  onSuccess
}) => {
  const [form] = Form.useForm()
  const [confirmLoading, setConfirmLoading] = useState(false)
  const [courierList, setCourierList] = useState<PlatformUserTypes.CourierUserListDto[]>([])
  const [selectedDevices, setSelectedDevices] = useState<DeviceManagementTypes.DeviceListDto[]>([])
  const [platformOptions, setPlatformOptions] = useState<Record<string, { text: string }>>({})

  // 加载配送员列表
  const loadCourierList = async () => {
    try {
      const res = await getCourierUserList({ status: 1, pageSize: 1000 })
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        setCourierList(res.data.list)
      }
    } catch (e) {
      console.error('加载配送员列表失败:', e)
    }
  }

  // 加载电商平台列表
  const loadShopPlatformList = async () => {
    try {
      const res = await getShopPlatformList({ status: 1, pageSize: 100 })
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        const options: Record<string, { text: string }> = {}
        res.data.list.forEach((item: SystemConfigTypes.ShopPlatformListDto) => {
          options[item.id] = { text: item.name }
        })
        setPlatformOptions(options)
      }
    } catch (e) {
      console.error('获取电商平台列表失败:', e)
    }
  }

  // 组件挂载时加载数据
  useEffect(() => {
    if (open) {
      loadCourierList()
      loadShopPlatformList()
    }
  }, [open])

  // 弹窗打开时重置表单
  useEffect(() => {
    if (open) {
      form.resetFields()
      setSelectedDevices([])
    }
  }, [open, form])

  // 保存绑定
  const handleSave = async () => {
    try {
      const values = await form.validateFields()
      setConfirmLoading(true)

      if (selectedDevices.length === 0) {
        message.error('请选择柜机')
        setConfirmLoading(false)
        return
      }

      const res = await addDeliveryReturn({
        deviceId: selectedDevices.map(d => d.id),
        platformId: values.platformId,
        courierId: values.courierId
      })

      if (res.code === ResultEnum.SUCCESS) {
        message.success('绑定关系已创建')
        onSuccess()
      } else {
        message.error(res.message || '创建失败')
      }
    } catch (e) {
      console.error(e)
    } finally {
      setConfirmLoading(false)
    }
  }

  return (
    <Modal
      title="新增绑定关系"
      open={open}
      onCancel={onCancel}
      onOk={handleSave}
      confirmLoading={confirmLoading}
      width={720}
    >
      <Form form={form} layout="vertical" style={{ marginTop: 16 }}>
        <Form.Item
          label="选择柜机"
          name="deviceId"
          rules={[{ required: true, message: '请选择柜机' }]}
        >
          <DeviceSelector value={selectedDevices} onChange={setSelectedDevices} multiple={true} />
        </Form.Item>

        <Form.Item
          label="电商平台"
          name="platformId"
          rules={[{ required: true, message: '请选择电商平台' }]}
        >
          <Select placeholder="请选择电商平台">
            {Object.entries(platformOptions).map(([key, option]) => (
              <Select.Option key={key} value={Number(key)}>
                {option.text}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        <Form.Item
          label="配送员"
          name="courierId"
          rules={[{ required: true, message: '请选择配送员' }]}
        >
          <Select
            placeholder="请选择配送员"
            showSearch
            filterOption={(input, option) =>
              String(option?.children || '')
                .toLowerCase()
                .includes(input.toLowerCase())
            }
          >
            {courierList.map(courier => (
              <Select.Option key={courier.id} value={courier.id}>
                {courier.realName} ({courier.phone})
              </Select.Option>
            ))}
          </Select>
        </Form.Item>
      </Form>
    </Modal>
  )
}

export default AddDeliveryReturnModal
